"""CLI entry point for the review orchestrator.

Usage (typically via the review skill wrapper, but works standalone):

    python orchestrator/cli.py [--pr N] [--guidance "text"]
        [--scoring categorical|simple] [--project-root PATH]
        [--max-agents 16] [--parallel 4] [--timeout 600] [--dry-run]
"""

import argparse
import os
import sys
from pathlib import Path

PLUGIN_ROOT = Path(__file__).resolve().parent.parent
if str(PLUGIN_ROOT) not in sys.path:
    sys.path.insert(0, str(PLUGIN_ROOT))

from orchestrator import pipeline  # noqa: E402


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        prog="review-orchestrator", description=__doc__
    )
    parser.add_argument("--pr", type=int, default=None, help="PR number to scope to")
    parser.add_argument("--guidance", default="", help="free-form review guidance")
    parser.add_argument(
        "--scoring",
        choices=["categorical", "simple"],
        default="categorical",
        help="categorical: five-dimension rubric with justifications "
        "(more output tokens per finding, stronger noise filtering); "
        "simple: severity+confidence (cheaper, lighter)",
    )
    parser.add_argument(
        "--project-root", default=os.getcwd(), help="project to review"
    )
    parser.add_argument("--max-agents", type=int, default=16)
    parser.add_argument("--parallel", type=int, default=4)
    parser.add_argument(
        "--timeout", type=int, default=600, help="per-agent timeout in seconds"
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="compute scope and print the selector prompt without dispatching agents",
    )
    args = parser.parse_args(argv)

    options = pipeline.Options(
        project_root=str(Path(args.project_root).resolve()),
        pr_number=args.pr,
        guidance=args.guidance,
        scoring=args.scoring,
        max_agents=args.max_agents,
        parallel=args.parallel,
        timeout_s=args.timeout,
        dry_run=args.dry_run,
    )
    try:
        return pipeline.run_review(options)
    except pipeline.PipelineError as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())
